// All project content. Sourced from the Systems Lab spec (prompt1 §3–4, prompt2 §5–6).
// Diagram nodes reference the real files of the in-browser mini engines.

export type Hue = "green" | "cyan" | "amber" | "magenta" | "blue" | "orange" | "violet" | "yellow" | "teal" | "coral";
export type DNode = { id: string; label: string; col: number; row: number; desc: string; file?: string; kind?: "store" | "external" | "boundary" };
export type DEdge = { from: string; to: string; label?: string };
export type Concept = { title: string; simple: string; detail: string; mistake: string };
export type Experiment = { title: string; objective: string; steps: string; expect: string };

export type Project = {
  slug: string;
  num: string;
  name: string;
  lang: "Rust" | "C++";
  hue: Hue;
  difficulty: 1 | 2 | 3 | 4 | 5;
  effort: string;
  tagline: string;
  concepts: string[];
  mini: { badge: string; real: string[]; simulated: string[] };
  overview: { what: string; why: string; usedIn: string[]; alternatives: string[]; limits: string[] };
  scope: string[];
  diagram: { nodes: DNode[]; edges: DEdge[] };
  internals: Concept[];
  experiments: Experiment[];
  metrics: string[];
  build: { step: string; detail: string }[];
  stack: string[];
};

